SELECT TO_CHAR(DATE_FROM_PARTS(t.ANO,t.MES,1),'YYYY-MM') mes, ROUND(SUM(IFF(f.VALOR_VENTA_OFERTA>0,f.VALOR_VENTA_OFERTA,0))) bruta, ROUND(-SUM(IFF(f.VALOR_VENTA_OFERTA<0,f.VALOR_VENTA_OFERTA,0))) devol, MAX(t.NUM_DIA_MES) ult_dia FROM JM_SILVER_PRD_DB.JM_VENTAS_LEGACY.FACT_FACTURACION f JOIN JM_SILVER_PRD_DB.JM_CORE_LEGACY.DIM_UNIDAD_TIEMPO t ON f.UNIDAD_TIEMPO_ID=t.ID WHERE t.ANO>=2025 GROUP BY 1 ORDER BY 1